SELECT social_account_id, user_id, provider, provider_user_id, connected_at
FROM social_accounts
WHERE provider = #{provider}
  AND provider_user_id = #{providerUserId}

SELECT token_id, user_id, token_hash, expires_at, created_at
FROM refresh_tokens
WHERE user_id = #{userId} AND token_hash = #{tokenHash}
